//! 🧪️ Selected SET constructors preserve all original member drafts under progressive original loans.
use super::*;
use semio_framework_plugin::app_testing::OriginalWorkFixture;
pub(super) fn retire<T:RetireOwned>(caller:&mut OriginalWorkFixture,owner:&mut Option<T>){let mut close=RetainedCloneClose::default();for turn in 0..100000{if owner.is_none()&&close.is_empty(){break;}let demand=close.next_owner_demands::<T>(owner.is_some(),&None,4096).unwrap();caller.turn(OriginalWorkFixture::stock(),|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,demand,|grant|if close.is_empty(){close.begin_granted(owner,grant)?.ok_or_else(invalid)}else{close.step_granted(grant)})?;Ok(())})).unwrap();assert!(turn<99999);}assert!(owner.is_none()&&close.is_empty());}
fn source()->DslValue{let raw="a".repeat(63)+"€"+&"ä".repeat(40);DslValue::Object(vec![("name".into(),DslValue::String("IFCPROPERTYSETDEFINITIONSET".into())),("items".into(),DslValue::Array(vec![DslValue::Object(vec![("kind".into(),DslValue::String("aggregate".into())),("value".into(),DslValue::Array(["7".to_owned(),"7".to_owned(),"".to_owned(),"-".to_owned(),raw].into_iter().map(|raw|DslValue::Object(vec![("kind".into(),DslValue::String("reference".into())),("value".into(),DslValue::String(raw))])).collect()))])]))])}
#[test]
fn original_set_constructor_copy_keeps_order_duplicates_partial_words_utf8_and_every_denied_axis(){
 let source=source();let input=Input{source:Some(&source),name:"IFCPROPERTYSETDEFINITIONSET",kind:InputKind::Set,fill:false};let mut caller=OriginalWorkFixture::new();let mut copy=Some(TypedCopy::default());let mut output=None;
 for turn in 0..1000000{let demand=copy.as_ref().unwrap().demands(&input).unwrap();let(repeated,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||copy.as_ref().unwrap().demands(&input));assert_eq!(repeated.unwrap(),demand);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for axis in 0..6{let mut denied=OriginalWorkFixture::stock();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&input,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&input,cx)).unwrap(){break;}assert!(turn<999999);}
 assert!(caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().take(&mut output,cx)).unwrap());assert_eq!(output.as_ref(),Some(&source));retire(&mut caller,&mut copy);retire(&mut caller,&mut output);caller.finish();
}
#[test]
fn original_set_constructor_copy_cancelled_prefixes_and_substituted_sources_stay_retirable(){
 let source=source();let replacement=source.clone();let input=Input{source:Some(&source),name:"IFCPROPERTYSETDEFINITIONSET",kind:InputKind::Set,fill:false};let mut total=None;
 for prefix in std::iter::once(None).chain((0..1000000).map(Some)){if prefix.is_some_and(|prefix|total.is_some_and(|total|prefix>=total)){break;}let mut caller=OriginalWorkFixture::new();let mut copy=Some(TypedCopy::default());for turn in 0..1000000{if turn>0{let swapped=Input{source:Some(&replacement),..input};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&swapped,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if prefix==Some(turn){caller.cancel().cancel_now();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&input,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));break;}if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&input,cx)).unwrap(){total=Some(turn+1);assert!(prefix.is_none());break;}assert!(turn<999999);}retire(&mut caller,&mut copy);caller.finish();}assert!(total.is_some());
}
#[test]
fn selected_set_constructor_without_an_original_child_stays_itemless(){
 let input=Input{source:None,name:"IFCPROPERTYSETDEFINITIONSET",kind:InputKind::Set,fill:false};let mut caller=OriginalWorkFixture::new();let mut copy=Some(TypedCopy::default());let mut output=None;for turn in 0..100000{if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&input,cx)).unwrap(){break;}assert!(turn<99999);}assert!(caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().take(&mut output,cx)).unwrap());assert!(matches!(output.as_ref().unwrap().get("items"),Some(DslValue::Array(items))if items.is_empty()));retire(&mut caller,&mut copy);retire(&mut caller,&mut output);caller.finish();
}
